class TestTodoMiddlewareAgentGraphIntegration:
    def test_reuses_thread_state_todos_schema_in_real_agent_graph(self):
        mw = TodoMiddleware()
        model = _CapturingFakeMessagesListChatModel(
            responses=[
                AIMessage(
