    def test_merges_subagent_usage_by_message_position_when_ai_message_ids_are_missing(self, monkeypatch):
        middleware = TokenUsageMiddleware()
        first_dispatch = AIMessage(
            content="",
            tool_calls=[{"id": "task:first", "name": "task", "args": {}}],
        )
        second_dispatch = AIMessage(
            content="",
            tool_calls=[
                {"id": "task:second-a", "name": "task", "args": {}},
                {"id": "task:second-b", "name": "task", "args": {}},
            ],
        )
        messages = [
            first_dispatch,
            ToolMessage(content="first", tool_call_id="task:first"),
            second_dispatch,
            ToolMessage(content="second-a", tool_call_id="task:second-a"),
            ToolMessage(content="second-b", tool_call_id="task:second-b"),
            AIMessage(content="done"),
        ]
        cached_usage = {
            "task:second-a": {"input_tokens": 10, "output_tokens": 5, "total_tokens": 15},
            "task:second-b": {"input_tokens": 20, "output_tokens": 7, "total_tokens": 27},
        }

        task_tool_module = importlib.import_module("deerflow.tools.builtins.task_tool")
        monkeypatch.setattr(
            task_tool_module,
            "pop_cached_subagent_usage",
            lambda tool_call_id: cached_usage.pop(tool_call_id, None),
        )

        result = middleware.after_model({"messages": messages}, _make_runtime())

        assert result is not None
        usage_updates = [message for message in result["messages"] if getattr(message, "usage_metadata", None)]
        assert len(usage_updates) == 1
        updated = usage_updates[0]
        assert updated.tool_calls == second_dispatch.tool_calls
        assert updated.usage_metadata == {
            "input_tokens": 30,
            "output_tokens": 12,
            "total_tokens": 42,
        }


class TestBuildTodoActions:
    def test_duplicate_content_emits_todo_remove(self):
        """When next_todos has duplicate content entries that exhaust previous_by_content,
        the positional fallback must not consume an unrelated previous todo as matched.
        The unrelated previous entry should still produce a todo_remove action."""
        previous = [
            {"content": "A", "status": "pending"},
            {"content": "B", "status": "pending"},
        ]
        next_todos = [
            {"content": "A", "status": "in_progress"},
            {"content": "A", "status": "completed"},
        ]
        actions = _build_todo_actions(previous, next_todos)
        assert any(a.get("kind") == "todo_remove" and a.get("content") == "B" for a in actions), f"Expected todo_remove for B but got: {actions}"

"""Tests for task exception metadata produced by ToolErrorHandlingMiddleware."""

from __future__ import annotations

import asyncio

from langchain_core.messages import ToolMessage
from langgraph.types import Command

from deerflow.agents.middlewares.tool_error_handling_middleware import (
    ToolErrorHandlingMiddleware,
)
from deerflow.subagents.status_contract import (
    SUBAGENT_ERROR_KEY,
    SUBAGENT_STATUS_KEY,
)


class _FakeRequest:
    """Stand-in for ``ToolCallRequest`` used by the middleware."""

    def __init__(self, tool_name: str, tool_call_id: str = "call-1") -> None:
        self.tool_call = {"name": tool_name, "id": tool_call_id}


def test_task_tool_exception_returns_failed_metadata():
    middleware = ToolErrorHandlingMiddleware()
    request = _FakeRequest("task")

    def handler(_req):
        raise RuntimeError("blew up during execution")

    result = middleware.wrap_tool_call(request, handler)

    assert isinstance(result, ToolMessage)
    assert result.additional_kwargs.get(SUBAGENT_STATUS_KEY) == "failed"
    assert "RuntimeError" in result.additional_kwargs.get(SUBAGENT_ERROR_KEY, "")


def test_async_task_tool_exception_returns_failed_metadata():
    middleware = ToolErrorHandlingMiddleware()
    request = _FakeRequest("task")

    async def handler(_req):
        raise RuntimeError("async boom")

    result = asyncio.run(middleware.awrap_tool_call(request, handler))

    assert isinstance(result, ToolMessage)
    assert result.additional_kwargs.get(SUBAGENT_STATUS_KEY) == "failed"
    assert "RuntimeError" in result.additional_kwargs.get(SUBAGENT_ERROR_KEY, "")


def test_successful_plain_task_tool_message_is_not_stamped_from_content():
    middleware = ToolErrorHandlingMiddleware()
    request = _FakeRequest("task")

    def handler(_req):
        return ToolMessage(content="Task Succeeded. Result: ok", tool_call_id="call-1", name="task")

    result = middleware.wrap_tool_call(request, handler)

    assert isinstance(result, ToolMessage)
    assert SUBAGENT_STATUS_KEY not in (result.additional_kwargs or {})


def test_does_not_stamp_non_task_tool_exception():
    middleware = ToolErrorHandlingMiddleware()
    request = _FakeRequest("bash")

    def handler(_req):
        raise RuntimeError("command failed")

    result = middleware.wrap_tool_call(request, handler)

    assert isinstance(result, ToolMessage)
    assert SUBAGENT_STATUS_KEY not in (result.additional_kwargs or {})


def test_task_command_with_metadata_bypasses_middleware_stamp():
    middleware = ToolErrorHandlingMiddleware()
    request = _FakeRequest("task")
    command = Command(
        update={
            "messages": [
                ToolMessage(
                    "Task Succeeded. Result: ok",
                    tool_call_id="call-1",
                    name="task",
                    additional_kwargs={"subagent_status": "completed", "subagent_result_brief": "ok"},
                )
            ]
        }
    )

    assert middleware.wrap_tool_call(request, lambda _req: command) is command


def test_additional_kwargs_round_trip_via_json():
    msg = ToolMessage(
        content="Task Succeeded. Result: ok",
        tool_call_id="call-1",
        name="task",
        additional_kwargs={SUBAGENT_STATUS_KEY: "completed", SUBAGENT_ERROR_KEY: ""},
    )
    serialised = msg.model_dump_json()
    restored = ToolMessage.model_validate_json(serialised)
    assert restored.additional_kwargs.get(SUBAGENT_STATUS_KEY) == "completed"

